  /// </summary>
  /// <remarks>
  /// <para>
  /// The value returned may be either a local file path or a URI.
  /// </para>
  /// </remarks>
  public static string ApplicationBaseDirectory => AppDomain.CurrentDomain.BaseDirectory;

